from collections import defaultdict, deque

def shortest_path(graph, source, target):
    # Initialize queue with the source node and initial distance
    queue = deque([(source, [source])])
    # Dictionary to hold the shortest known distance to each node
    dist_to = {source: 0}

    while queue:
        current_node, path = queue.popleft()

        for neighbour, weight in graph.get(current_node, []):
            distance = dist_to[current_node] + weight

            if neighbour not in dist_to or distance < dist_to[neighbour]:
                dist_to[neighbour] = distance
                queue.append((neighbour, path + [neighbour]))

                # If we have reached the target, return the distance and the path
                if neighbour == target:
                    return (distance, path)

    # If the target node is unreachable, return infinity and None
    return (float("inf"), None)

