from collections import deque

def shortest_path(graph, source, target):
    # If the target is the same as source, it's trivially reachable
    if source == target:
        return (0, [source])

    # Initialize the distances to all nodes as infinity, except the source node
    distances = {node: float('inf') for node in graph}
    distances[source] = 0

    # Initialize the path dictionary with None values
    path = {node: None for node in graph}

    # Queue for BFS
    queue = deque([(source, [source])])

    while queue:
        current_node, current_path = queue.popleft()

        for neighbor, weight in graph[current_node]:
            if distances[neighbor] > distances[current_node] + weight:
                distances[neighbor] = distances[current_node] + weight
                path[neighbor] = current_node
                queue.append((neighbor, current_path + [neighbor]))

                # If we reach the target, reconstruct the path
                if neighbor == target:
                    reconstruct_path = []
                    while neighbor is not None:
                        reconstruct_path.append(neighbor)
                        neighbor = path[neighbor]
                    reconstruct_path.reverse()
                    return (distances[target], reconstruct_path)

    # If we exit the loop without finding a path, the target is unreachable
    return (float('inf'), None)

