    distances[source] = 0
    visited = set()
    predecessors = {}

    while target not in visited:
        current_distance = infinity
        current_node = None

        for node in graph:
            if node in visited:
                continue

            distance_to_node = distances[node] + sum(weight for neighbour, weight in graph[node] if neighbour in visited)
            if distance_to_node < current_distance:
                current_distance = distance_to_node
                current_node = node

        if current_node is None:
            return infinity, None

        visited.add(current_node)
        for neighbour, weight in graph[current_node]:
            if neighbour not in visited:
                old_distance = distances[neighbour]
                new_distance = distances[current_node] + weight
                if new_distance < old_distance:
                    distances[neighbour] = new_distance
                    predecessors[neighbour] = current_node

    path = reconstruct_path(predecessors, target)
    return distances[target], path

